def _generate_historical_data(self, symbol: str, timeframe: str,
                              start_date: str, end_date: str,
                              adjustment: str) -> Dict:
    """Fetch real historical data using Yahoo Finance API"""

    try:
        import requests

        # Map timeframe to Yahoo interval
        interval_map = {
            "1d": "1d",
            "1w": "1wk", 
            "1mo": "1mo"
        }
        interval = interval_map.get(timeframe, "1d")

        # Yahoo Finance chart endpoint
        url = f"https://query1.finance.yahoo.com/v8/finance/chart/{symbol}"
        params = {
            'period1': int(datetime.strptime(start_date, "%Y-%m-%d").timestamp()),
            'period2': int(datetime.strptime(end_date, "%Y-%m-%d").timestamp()),
            'interval': interval,
            'events': 'div,split'
        }
        headers = {
            'User-Agent': 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36'
        }

        resp = requests.get(url, params=params, headers=headers, timeout=15)

        if resp.status_code != 200:
            raise Exception(f"HTTP {resp.status_code}")

        data = resp.json()

        if "chart" not in data or "result" not in data["chart"] or data["chart"]["result"] is None:
            raise Exception("No data returned")

        result = data["chart"]["result"][0]
        timestamps = result.get("timestamp", [])
        indicators = result.get("indicators", {}).get("quote", [{}])[0]

        if not timestamps:
            raise Exception("No timestamps")

        candles = []
        for i, ts in enumerate(timestamps):
            date = datetime.fromtimestamp(ts).strftime("%Y-%m-%d")

            candle = {
                "date": date,
                "open": round(indicators["open"][i], 2) if indicators.get("open") and i < len(indicators["open"]) else 0,
                "high": round(indicators["high"][i], 2) if indicators.get("high") and i < len(indicators["high"]) else 0,
                "low": round(indicators["low"][i], 2) if indicators.get("low") and i < len(indicators["low"]) else 0,
                "close": round(indicators["close"][i], 2) if indicators.get("close") and i < len(indicators["close"]) else 0,
                "volume": int(indicators["volume"][i]) if indicators.get("volume") and i < len(indicators["volume"]) else 0,
            }

            if candle["close"] > 0 and candle["volume"] > 0:
                candle["amount"] = round(candle["close"] * candle["volume"], 2)
                candles.append(candle)

        if not candles:
            raise Exception("No valid candles")

        return {
            "symbol": symbol,
            "timeframe": timeframe,
            "adjustment": adjustment,
            "start_date": start_date,
            "end_date": end_date,
            "candle_count": len(candles),
            "candles": candles,
            "source": "yahoo-api"
        }

    except Exception as e:
        print(f"   [WARN] Yahoo API error: {str(e)[:50]}, using fallback")
        return self._generate_fallback_data(symbol, timeframe, start_date, end_date)

def _generate_financial_data(self, symbol: str, report_type: str, 
                             periods: int) -> Dict:
    """Fetch real financial data using Yahoo Finance API"""

    try:
        import requests

        # Yahoo Finance financials summary endpoint
        url = f"https://query1.finance.yahoo.com/v10/finance/quoteSummary/{symbol}"
        params = {
            'modules': 'financialData,defaultKeyStatistics,balanceSheetHistory,incomeStatementHistory'
        }
        headers = {
            'User-Agent': 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36'
        }

        resp = requests.get(url, params=params, headers=headers, timeout=15)

        if resp.status_code != 200:
            raise Exception(f"HTTP {resp.status_code}")

        data = resp.json()

        if "quoteSummary" not in data or "result" not in data["quoteSummary"] or data["quoteSummary"]["result"] is None:
            raise Exception("No data returned")

        result = data["quoteSummary"]["result"][0]
        financial_data = result.get("financialData", {})
        key_stats = result.get("defaultKeyStatistics", {})

        # Extract key financial metrics
        report = {
            "period": datetime.now().strftime("%Y-%m-%d"),
            "revenue": financial_data.get("totalRevenue", {}).get("raw", 0),
            "gross_profit": financial_data.get("grossProfit", {}).get("raw", 0),
            "operating_income": financial_data.get("operatingIncome", {}).get("raw", 0),
            "net_income": financial_data.get("netIncomeToCommon", {}).get("raw", 0),
            "eps": key_stats.get("epsTrailingTwelveMonths", {}).get("raw", 0),
            "ebitda": financial_data.get("ebitda", {}).get("raw", 0),
            "total_assets": 0,
            "total_liabilities": 0,
            "shareholders_equity": 0,
        }

        return {
            "symbol": symbol,
            "report_type": report_type,
            "periods": 1,
